```yaml
name: Auto‑assign milestone

on:
  pull_request:
    types: [opened, synchronize, reopened, edited]

jobs:
  assign-milestone:
    runs-on: ubuntu-latest
    steps:
      - name: Assign milestone
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const targetBranch = pr.base.ref;
            const repo = context.repo;

            // Helper to get milestone number by title
            async function getMilestoneNumberByTitle(title) {
              const { data: milestones } = await github.rest.issues.listMilestones({
                owner: repo.owner,
                repo: repo.repo,
                state: 'all',
                per_page: 100
              });
              const milestone = milestones.find(m => m.title === title);
              return milestone ? milestone.number : null;
            }

            // Helper to get open milestones sorted by number
            async function getOpenMilestones() {
              const { data: milestones } = await github.rest.issues.listMilestones({
                owner: repo.owner,
                repo: repo.repo,
                state: 'open',
                per_page: 100
              });
              return milestones;
            }

            // Helper to get closed milestones sorted by number
            async function getClosedMilestones() {
              const { data: milestones } = await github.rest.issues.listMilestones({
                owner: repo.owner,
                repo: repo.repo,
                state: 'closed',
                per_page: 100
              });
              return milestones;
            }

            // Assign a milestone to the PR
            async function assignMilestone(number) {
              await github.rest.issues.update({
                owner: repo.owner,
                repo: repo.repo,
                issue_number: pr.number,
                milestone: number
              });
            }

            async function main() {
              if (targetBranch === 'main') {
                const closed = await getClosedMilestones();
                const highestClosed = closed.reduce((max, m) => m.number > max ? m.number : max, 0);
                const open = await getOpenMilestones();
                const candidates = open.filter(m => m.number > highestClosed);
                if (candidates.length > 0) {
                  const chosen = candidates.reduce((min, m) => m.number < min.number ? m : min, candidates[0]);
                  await assignMilestone(chosen.number);
                }
              } else if (targetBranch.startsWith('release/')) {
                const releaseVersion = targetBranch.split('/')[1];
                const milestoneTitle = `${releaseVersion}.1`;
                const milestoneNumber = await getMilestoneNumberByTitle(milestoneTitle);
                if (milestoneNumber) {
                  await assignMilestone(milestoneNumber);
                }
              }
            }

            main();
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
```

